    def maxWeight(self, pizzas: List[int]) -> int:
        pizzas.sort(reverse=True)
        n = len(pizzas)
        d = n // 4
        odd = (d + 1) // 2
        even = d // 2
        total = sum(pizzas[:odd])
        for i in range(even):
            total += pizzas[odd + 2 * i + 1]
        return total
